package com.aiot.log.controller;
import com.aiot.log.common.ApiResponse; import com.aiot.log.dto.EnvironmentSpaceRequest; import com.aiot.log.service.EnvironmentSpaceService; import com.aiot.log.service.EnvironmentOutdoorService; import com.aiot.log.vo.EnvironmentSpaceVO; import com.aiot.log.vo.EnvironmentOutdoorReadingVO; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/environment-spaces") @Tag(name="环境监测",description="室外天气、空气质量与未来室内传感器的空间配置") public class EnvironmentSpaceController { private final EnvironmentSpaceService service; private final EnvironmentOutdoorService outdoor; public EnvironmentSpaceController(EnvironmentSpaceService s,EnvironmentOutdoorService o){service=s;outdoor=o;} @GetMapping public ApiResponse<List<EnvironmentSpaceVO>> list(){return ApiResponse.success(service.list());} @GetMapping("/{id}/outdoor") public ApiResponse<EnvironmentOutdoorReadingVO> latest(@PathVariable Long id){return ApiResponse.success(outdoor.latest(id));} @PostMapping("/{id}/outdoor/refresh") public ApiResponse<EnvironmentOutdoorReadingVO> refresh(@PathVariable Long id){return ApiResponse.success(outdoor.refresh(id));} @PostMapping public ApiResponse<EnvironmentSpaceVO> create(@Valid @RequestBody EnvironmentSpaceRequest r){return ApiResponse.success(service.create(r));} @PutMapping("/{id}") public ApiResponse<EnvironmentSpaceVO> update(@PathVariable Long id,@Valid @RequestBody EnvironmentSpaceRequest r){return ApiResponse.success(service.update(id,r));} @DeleteMapping("/{id}") public ApiResponse<Void> delete(@PathVariable Long id){service.delete(id);return ApiResponse.success();}}
